rulesets.pack-1:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /c_json_int_is_int/{doc} {
      allow get: if resource.data.n is int && resource.data.n == 1;
    }
    match /c_json_float_is_float/{doc} {
      allow get: if resource.data.f is float;
    }
    match /c_json_2_0_is_float/{doc} {
      allow get: if resource.data.g is float;
    }
    match /c_json_2_0_is_int/{doc} {
      allow get: if resource.data.g is int;
    }
    match /c_json_1e2_is_int/{doc} {
      allow get: if resource.data.g is int && resource.data.g == 100;
    }
    match /c_json_int64_max/{doc} {
      allow get: if resource.data.g == 9223372036854775807;
    }
    match /c_json_2pow53_plus1_is_int/{doc} {
      allow get: if resource.data.g is int;
    }
    match /c_json_neg_zero/{doc} {
      allow get: if resource.data.g == 0 && resource.data.g is int;
    }
    match /c_json_ts_string_is_string/{doc} {
      allow get: if resource.data.t is string;
    }
    match /c_json_ts_string_is_timestamp/{doc} {
      allow get: if resource.data.t is timestamp;
    }
    match /c_json_null_field/{doc} {
      allow get: if resource.data.nul == null;
    }
    match /c_json_nested_list_map/{doc} {
      allow get: if resource.data.m.y == 'z' && resource.data.arr[2] == 3;
    }
    match /c_time_unset_is_timestamp/{doc} {
      allow get: if request.time is timestamp;
    }
    match /c_time_unset_eq_null/{doc} {
      allow get: if request.time == null;
    }
    match /c_time_default_is_timestamp/{doc} {
      allow get: if request.time is timestamp;
    }
    match /c_time_set/{doc} {
      allow get: if request.time == timestamp.date(2026, 3, 4) + duration.time(5, 6, 7, 123456789);
    }
    match /c_time_set_nanos/{doc} {
      allow get: if request.time.nanos() == 123456789;
    }
    match /c_time_set_millis_precision/{doc} {
      allow get: if request.time.toMillis() == 1772600767123;
    }
    match /c_time_offset/{doc} {
      allow get: if request.time == timestamp.date(2026, 3, 4);
    }
    match /c_time_no_fraction/{doc} {
      allow get: if request.time.nanos() == 0;
    }
    match /c_resource_absent_is_null/{doc} {
      allow get: if resource == null;
    }
    match /c_resource_absent_or_true/{doc} {
      allow get: if resource.data.n == 1 || true;
    }
    match /c_resource_null_is_null/{doc} {
      allow get: if resource == null;
    }
    match /c_resource_null_data/{doc} {
      allow get: if resource.data == null;
    }
    match /c_resource_null_data_or_true/{doc} {
      allow get: if resource.data.n == 1 || true;
    }
    match /c_resource_empty_map_data/{doc} {
      allow get: if resource.data.size() == 0;
    }
    match /c_resource_name/{doc} {
      allow get: if resource.__name__ == /databases/(default)/documents/c_resource_name/doc;
    }
    match /c_request_resource_null_on_get/{doc} {
      allow get: if request.resource == null;
    }
    match /c_request_path_value/{doc} {
      allow get: if request.path == /databases/(default)/documents/c_request_path_value/doc;
    }
    match /c_request_path_is_path/{doc} {
      allow get: if request.path is path;
    }
    match /c_request_method_get/{doc} {
      allow get: if request.method == 'get';
    }
    match /c_database_var/{doc} {
      allow get: if database == '(default)';
    }
    match /c_doc_var/{doc} {
      allow get: if doc == 'doc';
    }
    match /c_auth_uid/{doc} {
      allow get: if request.auth.uid == 'alice';
    }
    match /c_auth_token_email/{doc} {
      allow get: if request.auth.token.email == 'alice@example.com';
    }
    match /c_auth_token_list/{doc} {
      allow get: if request.auth.token.groups.hasAny(['g2']);
    }
    match /c_auth_token_missing_claim_get/{doc} {
      allow get: if request.auth.token.get('missing', false) == false;
    }
    match /c_auth_absent/{doc} {
      allow get: if request.auth == null;
    }
    match /c_auth_null/{doc} {
      allow get: if request.auth == null;
    }
    match /c_auth_null_uid/{doc} {
      allow get: if request.auth.uid == 'alice';
    }
    match /c_auth_null_uid_or_true/{doc} {
      allow get: if request.auth.uid == 'alice' || true;
    }
    match /c_auth_without_token/{doc} {
      allow get: if request.auth.token == null;
    }
    match /c_auth_uid_int/{doc} {
      allow get: if request.auth.uid is int;
    }
    match /c_request_keys/{doc} {
      allow get: if request.keys().hasAll(['auth', 'method', 'path', 'time']);
    }
    match /c_request_is_map/{doc} {
      allow get: if request is map && resource is map;
    }
    match /c_request_query_on_get/{doc} {
      allow get: if request.query == null;
    }
  }
}

